  'phonetics.rules_intro_title': '为什么韩文**写的**和**读的**不一样？',
  'phonetics.rules_intro_body': '韩文字母由 **世宗大王** 在 1443 年根据发音器官的形状创造——每个字母都对应一个“原始”发音。但当字母连成词，相邻发音会互相影响：**送气、鼻腔、舌位** 会本能地朝最省力的方向滑动，于是写法和实际读音就分了家。',
  'phonetics.rules_intro_divider': '下面 10 大变音规则',
  'phonetics.rules_intro_outro': '不是死规矩，而是“省力规律”——每条都听 2 遍真人录音，舌头自然就记住了。',
  'phonetics.order_eyebrow': '◆ 应用顺序 · 음운 규칙의 적용 순서',
  'phonetics.order_title': '一个字发生多种音变时，谁先谁后？',
  'phonetics.order_body': '遇到一个词读音困惑时，按下面顺序推导：**先判断收音本音 → 看后接什么 → 决定走连音还是中和 → 再看是否触发紧音化/鼻音化/送气化**。',
  'phonetics.order_s1_label': '中和',
  'phonetics.order_s1_desc': '如果这个字要单独发音（或后接辅音），先把 ㅅ/ㅆ/ㅈ/ㅊ/ㅌ/ㅎ 变成 ㄷ；ㅋ/ㄲ 变 ㄱ；ㅍ 变 ㅂ。这是所有音变的起点。',
  'phonetics.order_s2_label': '连音判断',
  'phonetics.order_s2_desc': '看下一个音节：以元音开头且是助词/词尾 → 走本音连音；以元音开头但是独立实词 → 走代表音连音（절음법칙）。',
  'phonetics.order_s3_label': '组合音变',
