  'phonetics.rule_r08_f2_from': '收音 ㅍ',
  'phonetics.rule_r08_f2_to': '先变 ㅂ 再连',
  'phonetics.rule_r08_explanation': '关键在"后面接什么"：接助词/词尾（이/은/을/에…）→ 走一般连音，直接搬本音；接**独立的实词**（있다/없다/안/위/아래…）→ 两个实词之间有意群边界，先把收音中和成 7 代表音，再搬。这是《韩国标准发音法》第 15 条的规定，也是"넷 있어요 [네딛써요]"与"넷이 [네시]"读法不同的根源。',
  'phonetics.rule_r08_lg0_label': '形式形态素（走本音）',
  'phonetics.rule_r08_lg0_jamos': '助词 이/은/을/에 · 词尾 -아/어/으니',
  'phonetics.rule_r08_lg1_label': '实质形态素（走代表音）',
  'phonetics.rule_r08_lg1_jamos': '独立动/形/名词 있다/없다/안/위/앞',
  'phonetics.rule_r08_ex0': '有四个（넷+있다）',
  'phonetics.rule_r08_ex1': '四个（넷+主格이）',
  'phonetics.rule_r08_ex2': '衣服里面（옷+안）',
  'phonetics.rule_r08_ex3': '衣服（옷+主格이）',
  'phonetics.rule_r08_ex4': '不好吃（맛+없다）',
  'phonetics.rule_r08_ex5': '花前面（꽃+앞：ㅊ→ㄷ 连到 앞）',
  'phonetics.rule_r08_s0': '有四把椅子。（넷+独立动词 있다）',
  'phonetics.rule_r08_s1': '四个人一队。（넷+助词 이）',
  'phonetics.rule_r08_s2': '这食物不好吃。（맛+独立形容词 없다）',
  'phonetics.rule_r08_p0': '这是学习者最常错的：把它当"넷이+있어요"处理走本音，实际넷 和 있다 是两个实词，ㅅ 先中和成 ㄷ。',
  'phonetics.rule_r08_p1': '옷 后接实词 안（里面），先中和 ㅅ→ㄷ。若接助词 옷이 则 [오시]。',
  'phonetics.rule_r08_p2': '맛있다 [마싣따/마시따] 与 맛없다 [마덥따] 一个走连音一个走断音，因为都是实词组合但历史发音习惯不同 —— 맛없다 已固化为代表音连读。',
  'phonetics.rule_r02_title': '鼻音化',
  'phonetics.rule_r02_plain': '硬辅音 ㄱ/ㄷ/ㅂ 后面遇到鼻音 ㄴ/ㅁ，自己也跟着变成鼻音。',
  'phonetics.rule_r02_explanation': '字尾辅音后面紧跟鼻音 ㄴ 或 ㅁ 时，字尾辅音会被"传染"也变成对应鼻音——气流自然改走鼻腔，更省力。',
  'phonetics.rule_r02_ex0': '汤',
  'phonetics.rule_r02_ex1': '接受(定语)',
  'phonetics.rule_r02_ex2': '前门',
  'phonetics.rule_r02_ex3': '学年',
  'phonetics.rule_r02_ex4': '入门',
  'phonetics.rule_r02_ex5': '有(定语)',
  'phonetics.rule_r02_s0': '汤真好喝。',
  'phonetics.rule_r02_s1': '我年级高。',
  'phonetics.rule_r02_p0': '不要按写法直接念。ㄱ + ㅁ 必须触发鼻音化，ㄱ 变 ㅇ。',
  'phonetics.rule_r02_p1': 'ㅍ 先中和成 ㅂ，再遇 ㅁ 变 ㅁ。两步同时发生：中和 → 鼻音化。',
  'phonetics.rule_r03_title': '流音化',
  'phonetics.rule_r03_plain': 'ㄴ 和 ㄹ 挨在一起时，ㄴ 会被 ㄹ 同化也念成 ㄹ。',
  'phonetics.rule_r03_explanation': 'ㄴ 和 ㄹ 这两个音相邻时，舌头懒得切换，干脆把 ㄴ 也念成 ㄹ。不管 ㄴ 在前还是在后都一样。',
  'phonetics.rule_r03_ex0': '新罗',
  'phonetics.rule_r03_ex1': '室内',
  'phonetics.rule_r03_ex2': '汉拿山',
  'phonetics.rule_r03_ex3': '全罗道',
  'phonetics.rule_r03_ex4': '联络',
  'phonetics.rule_r03_ex5': '春节',
  'phonetics.rule_r03_s0': '这是新罗时代的文物。',
  'phonetics.rule_r03_s1': '明天一定要联系我。',
  'phonetics.rule_r04_title': '颚化',
  'phonetics.rule_r04_tag': '特定语境',
  'phonetics.rule_r04_plain': '字尾 ㄷ/ㅌ 后面接以 이 开头的助词时，会变成 ㅈ/ㅊ。',
  'phonetics.rule_r04_explanation': '舌头从 ㄷ/ㅌ 滑到 이 时，发音位置正好顺势变成更靠前的 ㅈ/ㅊ。最经典的例子：같이 念 가치、굳이 念 구지。',
  'phonetics.rule_r04_ex0': '一起',
  'phonetics.rule_r04_ex1': '非要',
  'phonetics.rule_r04_ex2': '日出',
  'phonetics.rule_r04_ex3': '粘贴',
  'phonetics.rule_r04_ex4': '推拉门',
  'phonetics.rule_r04_ex5': '汗垫',
  'phonetics.rule_r04_s0': '我们一起去吧？',
  'phonetics.rule_r04_s1': '没必要非那样。',
  'phonetics.rule_r05_title': '送气化',
  'phonetics.rule_r05_plain': 'ㅎ 和 ㄱ/ㄷ/ㅂ/ㅈ 碰到一起，合并成对应的送气音 ㅋ/ㅌ/ㅍ/ㅊ。',
  'phonetics.rule_r05_explanation': 'ㅎ 自带的气流，遇到旁边的平音就直接把它"吹"成送气音。ㅎ 在前在后都算。',
  'phonetics.rule_r05_ex0': '祝贺',
  'phonetics.rule_r05_ex1': '多',
  'phonetics.rule_r05_ex2': '入学',
  'phonetics.rule_r05_ex3': '猜中',
  'phonetics.rule_r05_ex4': '好',
  'phonetics.rule_r05_ex5': '放入',
  'phonetics.rule_r05_s0': '生日快乐！',
  'phonetics.rule_r05_s1': '天气真好。',
  'phonetics.rule_r05_p0': '不要把 ㅎ 单独发出。ㄱ + ㅎ 一定合并成 ㅋ，两个音变一个。',
  'phonetics.rule_r05_p1': '既不是 ㅎ 脱落也不是普通连音。ㅎ + ㄷ 送气化成 ㅌ。',
  'phonetics.rule_r06_title': '紧音化',
  'phonetics.rule_r06_plain': '字尾是 ㄱ/ㄷ/ㅂ 时，后面的平音会"紧"起来，变成双写紧音。',
  'phonetics.rule_r06_explanation': '前一个字以 ㄱ/ㄷ/ㅂ 收尾时，气流被堵住，后面的平音 ㄱ/ㄷ/ㅂ/ㅅ/ㅈ 只能"用力挤"出来，变成紧音。',
  'phonetics.rule_r06_ex0': '学校',
  'phonetics.rule_r06_ex1': '餐厅',
  'phonetics.rule_r06_ex2': '汤饭',
  'phonetics.rule_r06_ex3': '合格',
  'phonetics.rule_r06_ex4': '小',
  'phonetics.rule_r06_ex5': '入场',
  'phonetics.rule_r06_s0': '我去学校。',
  'phonetics.rule_r06_s1': '这家餐厅好吃。',
  'phonetics.rule_r06_p0': '第二个 ㄱ 必须紧音化。听起来像"哈古"是错的，应有明显的爆破感。',
  'phonetics.rule_r06_p1': '写 ㄷ 读 ㄸ。所有 ㄱ/ㄷ/ㅂ 收音后的 ㄷ 都要紧音化。',
  'phonetics.rule_r09_title': 'ㅎ 脱落',
  'phonetics.rule_r09_plain': '收音 ㅎ 后面接**元音**或 **ㄴ/ㅁ** 开头的词尾时，ㅎ 直接消失。',
  'phonetics.rule_r09_f0_from': 'ㅎ 收音',
  'phonetics.rule_r09_f0_to': 'ㅎ 消失',
  'phonetics.rule_r09_f1_to': 'ㄴ/ㄹ 保留，ㅎ 消失',
  'phonetics.rule_r09_f2_to': 'ㅎ 消失（变鼻音）',
  'phonetics.rule_r09_explanation': 'ㅎ 是韩语最"软"的辅音，收音位置本身就发不实，一旦后面碰到元音就直接省掉。这跟送气化（ㅎ+ㄱ→ㅋ）刚好相反——遇到 ㄱ/ㄷ/ㅂ/ㅈ 时用力吹成送气音；遇到元音就直接脱落。写法保留 ㅎ，但读音里没有。',
  'phonetics.rule_r09_ex0': '好（ㅎ 消失）',
  'phonetics.rule_r09_ex1': '多（ㄶ→ㄴ）',
  'phonetics.rule_r09_ex2': '不喜欢（ㅀ→ㄹ）',
  'phonetics.rule_r09_ex3': '放入',
  'phonetics.rule_r09_ex4': '没关系',
  'phonetics.rule_r09_ex5': '放下',
  'phonetics.rule_r09_s0': '天气好。',
  'phonetics.rule_r09_s1': '人很多。',
  'phonetics.rule_r09_s2': '没关系，别担心。',
  'phonetics.rule_r09_p0': '不要保留 ㅎ 的气声。收音 ㅎ + 元音 → ㅎ 完全消失。',
  'phonetics.rule_r09_p1': 'ㄶ 中的 ㅎ 消失，ㄴ 连到下一音节。别把 ㅎ 读出来。',
  'phonetics.rule_r10_title': '中和·代表音化',
  'phonetics.rule_r10_tag': '基础必会',
  'phonetics.rule_r10_plain': '所有收音在**没有下一音节可连**时，只能发 7 个代表音之一：ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅇ。',
  'phonetics.rule_r10_explanation': '韩语字母有 19 个辅音，但一个音节收尾时只能听见 7 种发音——这就是"中和"。字面上写 ㅅ/ㅆ/ㅈ/ㅊ/ㅌ/ㅎ 的收音，读到句末或后接辅音时全部念作 [ㄷ]。这是所有音变的起点：先中和到 7 代表音，再看要不要连音/鼻音化/紧音化。',
  'phonetics.rule_r10_lg0_label': 'ㄱ 组',
